using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Tilemaps;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;
public static class SceneryChecks {
 public static void Run(){try{var report=new List<string>();foreach(var p in Directory.GetFiles("Assets/Prefabs/Chunks","*.prefab",SearchOption.AllDirectories)){var source=PrefabUtility.LoadPrefabContents(p);var painted=PrefabUtility.LoadPrefabContents("Assets/Prefabs/PaintedChunks/"+Path.GetFileNameWithoutExtension(p)+"_Painted.prefab");int props=0,terrain=0;foreach(var map in source.GetComponentsInChildren<Tilemap>(true)){var target=painted.GetComponentsInChildren<Tilemap>(true).FirstOrDefault(t=>t.name==map.name || (map.gameObject==source && t.gameObject==painted));if(target==null)throw new Exception("Missing map "+p+" / "+map.name+" available="+string.Join(",",painted.GetComponentsInChildren<Tilemap>(true).Select(t=>t.name)));if(map.GetComponent<TilemapRenderer>()==null)continue;var visible=target.GetComponent<TilemapRenderer>().enabled?target:target.transform.Find("Original props").GetComponent<Tilemap>();foreach(var c in map.cellBounds.allPositionsWithin){if(!map.HasTile(c))continue;if(map.GetTransformMatrix(c)!=target.GetTransformMatrix(c))throw new Exception("Tile/collider changed "+p+c);if(PaintedVariantBuilder.IsTerrain(map.GetSprite(c))){terrain++;if(map.GetColliderType(c)!=Tile.ColliderType.None && target.GetColliderType(c)!=Tile.ColliderType.None)throw new Exception("Old terrain collision retained");if(visible==target || visible.HasTile(c))throw new Exception("Original terrain visible");}else {props++;if(map.GetTile(c)!=target.GetTile(c)||map.GetColliderType(c)!=target.GetColliderType(c))throw new Exception("Prop collision changed");if(visible.GetTile(c)!=map.GetTile(c)||visible.GetColor(c)!=map.GetColor(c)||visible.GetTransformMatrix(c)!=map.GetTransformMatrix(c))throw new Exception("Prop hidden "+map.GetSprite(c)?.name);}}}report.Add($"PASS {Path.GetFileName(p)}: {props} prop/decor tiles preserved; {terrain} terrain tiles replaced; prop collision preserved; terrain collision matches visual outline.");PrefabUtility.UnloadPrefabContents(source);PrefabUtility.UnloadPrefabContents(painted);}CheckSlope(report);File.WriteAllLines("scenery-results.txt",report);Render();EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 static void CheckSlope(List<string> report){
  EditorSceneManager.NewScene(NewSceneSetup.EmptyScene);Physics2D.simulationMode=SimulationMode2D.Script;
  var go=new GameObject("Slope");go.layer=8;var collider=go.AddComponent<PolygonCollider2D>();collider.pathCount=20;
  var high=AssetDatabase.LoadAssetAtPath<Tile>("Assets/Art/Painted/PhysicsTiles/Snowy_Tundra_16x16_Tileset_50.asset");var low=AssetDatabase.LoadAssetAtPath<Tile>("Assets/Art/Painted/PhysicsTiles/Snowy_Tundra_16x16_Tileset_51.asset");
  for(int x=-4;x<16;x++){var contour=PaintedVariantBuilder.TerrainContour((x%2==0?high:low).sprite);var offset=new Vector2(x+.5f,-Mathf.FloorToInt(x/2f)+.5f);collider.SetPath(x+4,contour.Select(p=>p+offset).ToArray());}
  Physics2D.SyncTransforms();
  for(float x=.05f;x<10;x+=.1f){var hit=Physics2D.Raycast(new Vector2(x,10),Vector2.down,30,1<<8);if(hit.collider!=collider||Mathf.Abs(hit.point.y-(1-x*.5f))>.002f)throw new Exception("Slope collision not continuous at "+x+" hit="+hit.point);}
  report.Add("PASS continuous slope: 100 ray samples match the rendered line across tile joins.");
  var actor=new GameObject("Player");var rb=actor.AddComponent<Rigidbody2D>();rb.gravityScale=4;actor.AddComponent<CapsuleCollider2D>().size=Vector2.one;var motor=actor.AddComponent<PlayerMovement>();motor.groundLayer=1<<8;motor.useAcceleration=false;rb.position=new Vector2(.2f,1.6f);
  var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;typeof(PlayerMovement).GetMethod("Awake",flags).Invoke(motor,null);
  for(int n=0;n<35;n++){Physics2D.SyncTransforms();typeof(PlayerMovement).GetMethod("FixedUpdate",flags).Invoke(motor,null);Physics2D.Simulate(.02f);}
  typeof(PlayerMovement).GetField("moveInput",flags).SetValue(motor,1f);
  for(int n=0;n<65;n++){Physics2D.SyncTransforms();typeof(PlayerMovement).GetMethod("FixedUpdate",flags).Invoke(motor,null);Physics2D.Simulate(.02f);if(n>12 && (!motor.isGrounded||Mathf.Abs(rb.rotation+26.565f)>1f))throw new Exception("Actual painted slope lost stable contact/angle: "+rb.position+" angle="+rb.rotation);}
  report.Add("PASS player traverses actual painted slope tiles with steady angle and grounded contact.");
 }
 static void Render(){EditorSceneManager.OpenScene("Assets/Scenes/PaintedDimension.unity");var camera=Camera.main;camera.orthographic=true;camera.orthographicSize=6f;camera.aspect=16f/9f;foreach(var c in UnityEngine.Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None))c.enabled=false;foreach(var sr in UnityEngine.Object.FindObjectsByType<SpriteRenderer>(FindObjectsSortMode.None))if(sr.sprite!=null){var m=new Material(sr.sharedMaterial);m.mainTexture=sr.sprite.texture;sr.sharedMaterial=m;}
 foreach(var p in new[]{"Chunk_03","Chunk_06","End_Chunk_01","Start_Chunk_01"}){var root=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/PaintedChunks/"+p+"_Painted.prefab"));root.transform.position=Vector3.zero;var maps=root.GetComponentsInChildren<Tilemap>();Bounds bounds=new Bounds();bool first=true;foreach(var map in maps){if(!map.name.StartsWith("Gnd"))continue;var b=map.localBounds;b.center+=map.transform.position;if(first){bounds=b;first=false;}else bounds.Encapsulate(b);}camera.transform.position=new Vector3(bounds.center.x,bounds.center.y+1,camera.transform.position.z);camera.orthographicSize=Mathf.Max(5,bounds.size.x/3.55f+.5f);foreach(var l in UnityEngine.Object.FindObjectsByType<Parallax>(FindObjectsSortMode.None)){typeof(Parallax).GetMethod("Start",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(l,null);typeof(Parallax).GetMethod("LateUpdate",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(l,null);}var rt=new RenderTexture(1600,900,24);rt.Create();RenderPipeline.SubmitRenderRequest(camera,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var image=new Texture2D(1600,900,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1600,900),0,0);image.Apply();File.WriteAllBytes("scenery-"+p+".png",image.EncodeToPNG());RenderTexture.active=null;rt.Release();UnityEngine.Object.DestroyImmediate(root);}}
}
